CREATE TABLE "events" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"created_by_user_id" uuid NOT NULL,
	"title" text NOT NULL,
	"description" text DEFAULT '' NOT NULL,
	"cover_asset_id" uuid,
	"format" text NOT NULL,
	"venue_name" text,
	"address" text,
	"starts_at" timestamp with time zone NOT NULL,
	"ends_at" timestamp with time zone NOT NULL,
	"status" text DEFAULT 'active' NOT NULL,
	"cancelled_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"deleted_at" timestamp with time zone,
	CONSTRAINT "events_format_chk" CHECK ("events"."format" in ('in_person','online')),
	CONSTRAINT "events_status_chk" CHECK ("events"."status" in ('active','cancelled')),
	CONSTRAINT "events_window_chk" CHECK ("events"."ends_at" > "events"."starts_at"),
	CONSTRAINT "events_location_chk" CHECK (("events"."format" = 'in_person' and "events"."venue_name" is not null and "events"."address" is not null and length(btrim("events"."venue_name")) > 0 and length(btrim("events"."address")) > 0) or ("events"."format" = 'online' and "events"."venue_name" is null and "events"."address" is null)),
	CONSTRAINT "events_cancelled_at_chk" CHECK (("events"."status" = 'cancelled') = ("events"."cancelled_at" is not null))
);
